const FIREBASE_CONFIG = {
  apiKey: "AIzaSyDJaYnVc7bEwImpkWtP73SCVcJRcvTcxAA",
  authDomain: "recipe-atlas-57923.firebaseapp.com",
  databaseURL: "https://recipe-atlas-57923-default-rtdb.europe-west1.firebasedatabase.app",
  projectId: "recipe-atlas-57923",
  storageBucket: "recipe-atlas-57923.firebasestorage.app",
  messagingSenderId: "705176176210",
  appId: "1:705176176210:web:ebc47f13be5b55712b018b"
};

async function fetchRating(dishKey) {
  const key = ratingKeyFor(dishKey);
  const res = await fetch(`${FIREBASE_CONFIG.databaseURL}/ratings/${key}.json`);
  if (!res.ok) throw new Error("fetch failed");
  const data = await res.json();
  return data && typeof data.count === "number" ? data : { total: 0, count: 0 };
}

async function submitRatingREST(dishKey, value) {
  const key = ratingKeyFor(dishKey);
  const current = await fetchRating(dishKey);
  const updated = { total: (current.total || 0) + value, count: (current.count || 0) + 1 };
  const res = await fetch(`${FIREBASE_CONFIG.databaseURL}/ratings/${key}.json`, {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(updated)
  });
  if (!res.ok) throw new Error("write failed");
  return updated;
}

function ratingKeyFor(dishKey) {
  return (dishKey || "").replace(/[.#$\[\]/]/g, "_");
}

function parseDurationParts(text) {
  if (!text) return null;
  const hourMatch = text.match(/(\d+)\s*(?:hours?|hrs?)/i);
  const minMatch = text.match(/(\d+)\s*(?:minutes?|mins?)/i);
  const dayMatch = text.match(/(\d+)\s*days?/i);
  if (!hourMatch && !minMatch && !dayMatch) return null;
  return {
    hours: hourMatch ? parseInt(hourMatch[1], 10) : 0,
    mins: minMatch ? parseInt(minMatch[1], 10) : 0,
    days: (!hourMatch && !minMatch && dayMatch) ? parseInt(dayMatch[1], 10) : 0
  };
}

function toISO8601Duration(text) {
  const parts = parseDurationParts(text);
  if (!parts) return undefined;
  if (parts.days > 0 && parts.hours === 0 && parts.mins === 0) return "P" + parts.days + "D";
  if (parts.hours === 0 && parts.mins === 0) return "PT0M";
  let iso = "PT";
  if (parts.hours > 0) iso += parts.hours + "H";
  if (parts.mins > 0) iso += parts.mins + "M";
  return iso;
}

function toISO8601TotalDuration(prepText, cookText) {
  const prep = parseDurationParts(prepText);
  const cook = parseDurationParts(cookText);
  if (!prep && !cook) return undefined;
  const p = prep || { hours: 0, mins: 0, days: 0 };
  const c = cook || { hours: 0, mins: 0, days: 0 };
  const totalMinsRaw = p.mins + c.mins;
  const carryHours = Math.floor(totalMinsRaw / 60);
  const remMins = totalMinsRaw % 60;
  const totalHours = p.hours + c.hours + carryHours;
  const totalDays = p.days + c.days;

  if (totalDays > 0) {
    let iso = "P" + totalDays + "D";
    if (totalHours > 0 || remMins > 0) {
      iso += "T";
      if (totalHours > 0) iso += totalHours + "H";
      if (remMins > 0) iso += remMins + "M";
    }
    return iso;
  }
  if (totalHours === 0 && remMins === 0) return "PT0M";
  let iso = "PT";
  if (totalHours > 0) iso += totalHours + "H";
  if (remMins > 0) iso += remMins + "M";
  return iso;
}

function stepShortName(text) {
  if (!text) return "";
  const firstSentence = text.split(/\.\s/)[0].replace(/\.$/, "");
  return firstSentence.length > 60 ? firstSentence.slice(0, 57).trim() + "…" : firstSentence;
}

function StarRating({ dish, onRatingLoaded }) {
  const [ratingData, setRatingData] = useState(null);
  const [myRating, setMyRating] = useState(null);
  const [hoverStar, setHoverStar] = useState(0);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState(false);

  const key = ratingKeyFor(dish);
  const localKey = `rated_${key}`;

  useEffect(() => {
    let cancelled = false;
    setRatingData(null);
    setError(false);
    setHoverStar(0);
    const stored = localStorage.getItem(localKey);
    setMyRating(stored ? parseInt(stored, 10) : null);

    fetchRating(dish).then((val) => {
      if (cancelled) return;
      setRatingData(val);
      if (onRatingLoaded) {
        onRatingLoaded(val.count > 0 ? { value: val.total / val.count, count: val.count } : null);
      }
    }).catch(() => { if (!cancelled) setError(true); });

    return () => { cancelled = true; };
    // eslint-disable-next-line
  }, [dish]);

  const submitRating = async (value) => {
    if (myRating || submitting) return;
    setSubmitting(true);
    try {
      const newVal = await submitRatingREST(dish, value);
      setRatingData(newVal);
      setMyRating(value);
      localStorage.setItem(localKey, String(value));
      if (onRatingLoaded) {
        onRatingLoaded(newVal.count > 0 ? { value: newVal.total / newVal.count, count: newVal.count } : null);
      }
    } catch (e) {
      setError(true);
    } finally {
      setSubmitting(false);
    }
  };

  if (error) return null;

  const average = ratingData && ratingData.count > 0 ? ratingData.total / ratingData.count : 0;
  const displayStars = myRating || hoverStar || Math.round(average);

  return (
    <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:20, flexWrap:"wrap" }}>
      <div style={{ display:"flex", gap:2 }}>
        {[1,2,3,4,5].map(n => (
          <span key={n}
            onClick={() => submitRating(n)}
            onMouseEnter={() => !myRating && !submitting && setHoverStar(n)}
            onMouseLeave={() => setHoverStar(0)}
            style={{
              cursor: myRating || submitting ? "default" : "pointer",
              fontSize: 22,
              lineHeight: 1,
              color: n <= displayStars ? "#c2622a" : "#e0d8cc",
              transition: "color .15s"
            }}
            aria-label={`Rate ${n} star${n === 1 ? "" : "s"}`}>
            ★
          </span>
        ))}
      </div>
      <div style={{ fontSize:12, color:"#9a9088", fontFamily:"Plus Jakarta Sans" }}>
        {ratingData === null ? (
          "Loading ratings…"
        ) : ratingData.count > 0 ? (
          <>{average.toFixed(1)} ({ratingData.count} rating{ratingData.count === 1 ? "" : "s"})</>
        ) : (
          "No ratings yet — be the first!"
        )}
        {myRating && <span style={{ color:"#c2622a", fontWeight:600, marginLeft:6 }}>· You rated this {myRating}★</span>}
      </div>
    </div>
  );
}


